from typing import List


def open_ticket_titles(client: httpx.Client, project: str) -> List[str]:
    """Fetch all open ticket titles for the given project, following paginated results."""
    titles = []
    status = "open"
    url = "/tickets"
    params = {"status": status, "project": project}

    while url is not None:
        response = client.get(url, params=params)
        response.raise_for_status()
        data = response.json()

        items = data.get("items", [])
        for item in items:
            title = item.get("title")
            if title is not None:
                titles.append(title)

        next_url = data.get("next")
        if next_url:
            # next_url is relative, keep status and project params for each request
            url = next_url
            params = {"status": status, "project": project}
        else:
            url = None

    return titles

import httpx


def make_proxied_client(proxy_url: str, base_url: str) -> httpx.Client:
    """Create an httpx.Client for base_url that routes all requests through proxy_url.

    Requests use a 5-second timeout and have header 'User-Agent: inventory-sync/1.0'.
    """
    headers = {"User-Agent": "inventory-sync/1.0"}
    timeout = 5.0
    # Use ProxyTransport to route all requests through the given proxy_url.
    transport = httpx.ProxyTransport(proxy_url)
    return httpx.Client(base_url=base_url, headers=headers, timeout=timeout, transport=transport)

