import re

def validate_signup(data: dict) -> dict:
    errors = {}
    cleaned = {}

    # Validate username: required, alphanumeric string
    username = data.get("username")
    if username is None:
        errors.setdefault("username", []).append("Missing data for required field.")
    elif not isinstance(username, str):
        errors.setdefault("username", []).append("Invalid type. Expected string.")
    elif not username.isalnum():
        errors.setdefault("username", []).append("Must be alphanumeric string.")
    else:
        cleaned["username"] = username

    # Validate email: required, valid e-mail address
    email = data.get("email")
    if email is None:
        errors.setdefault("email", []).append("Missing data for required field.")
    elif not isinstance(email, str):
        errors.setdefault("email", []).append("Invalid type. Expected string.")
    else:
        # Simple email regex: one @, non-empty local and domain parts, domain has at least one dot
        # This is a pragmatic validation, not full RFC compliance
        if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email):
            errors.setdefault("email", []).append("Invalid email address.")
        else:
            cleaned["email"] = email

    # Validate plan: optional, default "free", must be one of "free", "pro", "team"
    plan = data.get("plan", "free")
    if not isinstance(plan, str):
        errors.setdefault("plan", []).append("Invalid type. Expected string.")
    elif plan not in ("free", "pro", "team"):
        errors.setdefault("plan", []).append("Must be one of 'free', 'pro', 'team'.")
    else:
        cleaned["plan"] = plan

    # Validate age: optional, integer, 16 to 120 inclusive
    if "age" in data:
        age = data["age"]
        if not isinstance(age, int):
            errors.setdefault("age", []).append("Invalid type. Expected integer.")
        elif not (16 <= age <= 120):
            errors.setdefault("age", []).append("Must be between 16 and 120 inclusive.")
        else:
            cleaned["age"] = age

    if errors:
        exc = ValueError("Invalid signup data")
        exc.messages = errors
        raise exc

    return cleaned
